import { Component, OnDestroy } from '@angular/core';
import { FormArray, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Subscription } from 'rxjs';
import { StoreDbService, OBJECTNAME, USERROLE } from 'godigital-lib';
import { UtilsService, Users } from 'godigital-lib';

@Component({
    selector: 'app-profile-edit',
    templateUrl: './profile-edit.component.html'
})
export class ProfileEditComponent implements OnDestroy {
    loading = true;
    saving = false;
    error?: string;
    success = false;
    form: FormGroup;

    uid?: string;
    profile?: Users;
    sub?: Subscription;

    photoUrls: string[] = [];

    // 🔹 extra flags for Stripe buttons
    stripeActionRunning = false;

    constructor(
        private fb: FormBuilder,
        private storeDb: StoreDbService,
        public utilSvc: UtilsService
    ) {
        this.sub = this.storeDb.authState$.subscribe(async u => {
            this.uid = u?.uid || undefined;
            if (!this.uid) {
                this.loading = false;
                return;
            }
            await this.loadProfile();
        });

        // 🔹 2) role control is now editable (default: customer)
        this.form = this.fb.group({
            firstname: ['', Validators.required],
            lastname: ['', Validators.required],
            displayName: [''],
            phone: [''],
            country: [''],
            role: ['customer'],                 // was disabled before
            state: ['active'],
            socialnetwork: this.fb.array([] as any),
        });
    }

    ngOnDestroy(): void { this.sub?.unsubscribe(); }

    get socials() { return this.form.get('socialnetwork') as FormArray; }
    newSocial(label = '', url = '') { return this.fb.group({ label: [label], url: [url] }); }

    // 🔹 3) convenience getters for role / stripe in template
    get currentRole(): 'customer' | 'owner' | 'provider' | 'admin' {
        return (this.form.get('role')?.value as any) || 'customer';
    }

    get isOwnerOrProvider(): boolean {
        return this.currentRole === 'owner' || this.currentRole === 'provider';
    }

    get stripeConnected(): boolean {
        return !!this.profile?.stripeStandard?.stripe_user_id;
    }

    get stripeStatusLabel(): string {
        if (!this.isOwnerOrProvider) return 'Not applicable for this role';
        if (!this.stripeConnected) return 'Not connected';
        if (this.profile?.stripeStandard?.stripe_user_id) return this.profile.stripeStandard?.stripe_user_id;
        return 'Connected';
    }

    private async loadProfile() {
        this.loading = true;
        this.error = undefined;
        try {
            const doc = await this.storeDb.getObject(
                this.utilSvc.backendFBstoreId,
                this.utilSvc.mdb,
                OBJECTNAME.bnUsers,
                this.uid
            ) as Users | null;

            this.profile = doc || undefined;

            // 🔹 4) keep existing role if present, otherwise default to customer
            const role = doc?.role || 'customer';

            this.form.reset({
                firstname: doc?.firstname || '',
                lastname: doc?.lastname || '',
                displayName: doc?.displayName || '',
                phone: doc?.phone || '',
                country: doc?.country || '',
                role,
                state: doc?.state || 'active'
            });

            // socials
            this.socials.clear();
            (doc?.socialnetwork || []).forEach(s => this.socials.push(this.newSocial(s.label, s.url)));

            // photos
            this.photoUrls = (doc?.photos || []).slice();

            this.loading = false;
        } catch (e: any) {
            this.error = e?.message || 'Failed to load profile';
            this.loading = false;
        }
    }

    async onPhotosSelected(files: FileList | null) {
        if (!files?.length) return;
        if (!this.uid) return;
        this.saving = true;
        try {
            const dir = `users/${this.uid}`;
            for (const file of Array.from(files)) {
                const url = await this.storeDb.uploadObjects1(this.utilSvc.backendFBstoreId, file, dir) as string;
                this.photoUrls.push(url);
            }
        } catch (e: any) {
            this.error = e?.message || 'Photo upload failed';
        } finally {
            this.saving = false;
        }
    }

    // 🔹 5) Stripe connect: redirect to backend OAuth authorize endpoint
    connectStripe() {
        if (!this.uid) return;
        if (!this.isOwnerOrProvider) {
            this.error = 'Choose "Boat owner" or "Provider" role before connecting Stripe.';
            return;
        }

        this.stripeActionRunning = true;

        const accountType = this.currentRole === 'provider' ? 'provider' : 'owner';
        const params = new URLSearchParams({
            ownerId: this.uid,
            accountType,
        });

        // Frontend is presumably proxied to backend under /api
        window.location.href = this.utilSvc.backendURL + `/stripe/connect/authorize?${params.toString()}`;
    }

    // 🔹 6) Stripe disconnect: call /stripe/connect/deauthorize
    async disconnectStripe() {
        if (!this.uid) return;
        this.stripeActionRunning = true;
        this.error = undefined;

        try {
            const res = await fetch(this.utilSvc.backendURL + '/stripe/connect/deauthorize', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ ownerId: this.uid })
            });

            if (!res.ok) {
                const text = await res.text();
                throw new Error(text || 'Failed to disconnect Stripe');
            }

            // Locally clear Stripe fields in the profile snapshot
            if (this.profile) {
                this.profile = {
                    ...this.profile,
                    stripeStandard: undefined,
                };
            }
        } catch (e: any) {
            this.error = e?.message || 'Failed to disconnect Stripe';
        } finally {
            this.stripeActionRunning = false;
        }
    }

    async save() {
        this.error = undefined;
        this.success = false;
        if (!this.uid) return;

        this.saving = true;
        try {
            const v = this.form.value;
            const now = Date.now();

            // Preserve immutable/sensitive fields from existing doc
            const base: Partial<Users> = this.profile || { userId: this.uid, email: '' } as any;

            // 🔹 7) compute role safely: admin can only be preserved, not set by client
            let nextRole = USERROLE.CUSTOMER;
            if (base.role === USERROLE.ADMIN) {
                nextRole = USERROLE.ADMIN;
            } else if (v.role === USERROLE.OWNER || v.role === USERROLE.PROVIDER || v.role === USERROLE.CUSTOMER) {
                nextRole = v.role;
            }

            const payload: Users = {
                userId: this.uid,
                email: base.email || '',

                firstname: v.firstname || '',
                lastname: v.lastname || '',
                displayName: v.displayName || '',
                phone: v.phone || '',
                country: v.country || '',

                role: nextRole,

                photos: this.photoUrls,
                photoURL: this.photoUrls[0] || base.photoURL || '',

                socialnetwork: (v.socialnetwork || []).map((s: any) => ({
                    label: s.label || '',
                    url: s.url || ''
                })),

                emailverified: base.emailverified ?? false,
                provider: base.provider || 'firebase',

                state: (v.state as any) || base.state || 'active',

                // stripe fields preserved (or cleared locally via disconnectStripe)
                stripeStandard: base.stripeStandard || undefined,

                createdTS: base.createdTS || now,
                modifiedTS: now
            };

            await this.storeDb.updateObject(
                this.utilSvc.backendFBstoreId,
                this.utilSvc.mdb,
                OBJECTNAME.bnUsers,
                payload,
                this.uid
            );

            this.profile = payload;
            this.success = true;
        } catch (e: any) {
            this.error = e?.message || 'Failed to save profile';
        } finally {
            this.saving = false;
        }
    }
}
